WHITE = "W"
BLACK = "B"
NONE = ""


class Board:
    """Count territories of each player in a Go game."""

    def __init__(self, board):
        """Create a board from rows of Go intersections."""
        self._rows = tuple(board)
        self._h = len(self._rows)
        self._w = len(self._rows[0]) if self._rows else 0

    def _in_bounds(self, x, y):
        return 0 <= x < self._w and 0 <= y < self._h

    def _neighbors(self, x, y):
        if x > 0:
            yield x - 1, y
        if x + 1 < self._w:
            yield x + 1, y
        if y > 0:
            yield x, y - 1
        if y + 1 < self._h:
            yield x, y + 1

    def _find_region(self, x, y):
        pending = [(x, y)]
        visited = {(x, y)}
        region = set()
        border = set()

        while pending:
            current_x, current_y = pending.pop()
            region.add((current_x, current_y))

            for neighbor_x, neighbor_y in self._neighbors(
                current_x, current_y
            ):
                cell = self._rows[neighbor_y][neighbor_x]
                if cell == " ":
                    neighbor = (neighbor_x, neighbor_y)
                    if neighbor not in visited:
                        visited.add(neighbor)
                        pending.append(neighbor)
                elif cell == BLACK:
                    border.add(BLACK)
                elif cell == WHITE:
                    border.add(WHITE)

        owner = next(iter(border)) if len(border) == 1 else NONE
        return owner, region

    def territory(self, x, y):
        """Return the owner and empty region containing ``(x, y)``."""
        if not self._in_bounds(x, y):
            raise ValueError("Invalid coordinate")

        if self._rows[y][x] != " ":
            return NONE, set()

        return self._find_region(x, y)

    def territories(self):
        """Return all empty regions grouped by their owners."""
        result = {
            WHITE: set(),
            BLACK: set(),
            NONE: set(),
        }
        visited = set()

        for y in range(self._h):
            for x in range(self._w):
                point = (x, y)
                if self._rows[y][x] != " " or point in visited:
                    continue

                owner, region = self._find_region(x, y)
                visited.update(region)
                result[owner].update(region)

        return result

